-- ============================================================================
-- V1.55__seed_qa_baby_maternity.sql
-- ----------------------------------------------------------------------------
-- 迁移目的：为「AI客服学习知识库」(ai_cs_learned_kb) 灌注「母婴用品」
--           (baby_maternity) 一级分类下 5 个二级分类的种子 Q&A 数据。
--
-- 数据规模：5 个二级分类 × 30 条 = 150 条高价值 Q&A
--
-- 二级分类清单：
--   1. baby_formula  - 奶粉辅食（奶粉/辅食/米粉/果泥/配方奶）
--   2. baby_diaper   - 纸尿裤（纸尿裤/尿不湿/拉拉裤）
--   3. baby_toys     - 玩具书籍（玩具/积木/绘本/故事书/早教/拼图）
--   4. baby_pregnant - 孕妇用品（孕妇装/胎心仪/月子/待产/防辐射）
--   5. baby_clothes  - 婴幼服装（婴儿服/连体衣/肚兜/童装）
--
-- 数据特征：
--   - source_type = 'seed'（种子数据，非对话学习）
--   - review_status = 'approved'（已审核通过，可直接用于检索）
--   - enabled = 1 / vector_indexed = 1 / deleted = 0
--   - learn_batch_id = 'seed-v1.55'（批次标识，便于回溯）
--   - score 范围 70-95，按 Q&A 价值差异化
--   - content_hash = MD5(question + answer)，由 SQL 内联计算，保证唯一性
--
-- 写入策略：
--   通过 JOIN ai_cs_kb_category 按 code 关联 category_id，
--   仅匹配 parent_id IS NOT NULL 的二级分类，避免误绑一级分类。
--
-- 注意事项：
--   - 答复文本中的单引号已用两个单引号转义
--   - 不包含任何手机号、微信号、外链等敏感信息
--   - 母婴类商品答复侧重安全性与适用年龄，体现专业关怀
--   - 本脚本可重复执行（content_hash 唯一约束会阻止重复插入，
--     但建议仅在新建库或首次部署时执行）
-- ============================================================================


-- ============================================================================
-- 1. baby_formula（奶粉辅食）- 30 条
-- ============================================================================
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.55', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'baby_formula' AS code, '这个奶粉是几段的？多大宝宝喝' AS question, '亲，这款是2段奶粉，适合6-12个月的宝宝喝~1段是0-6个月，2段是6-12个月，3段是1-3岁。段数是按宝宝不同月龄的营养需求配方的，不能乱喝，要按月龄选对段数。如果您家宝宝是其他月龄，我店里也有1段和3段，您告诉我就行。这款是正品行货，有防伪码可以查验，宝宝入口的东西安全第一，您放心~' AS answer, '奶粉,段数,月龄,2段' AS tags, '奶粉段数与适用月龄说明' AS source_summary, 92 AS score
  UNION ALL SELECT 'baby_formula', '产地是哪里的？国产还是进口', '亲，这款是新西兰原装进口的，不是国产分装的~罐身上有原产国标识和中文标签，正规跨境进口，有海关检验检疫证明。新西兰的奶源在全球公认比较好，环境好牧场天然。这款是正品行货，支持扫码验真，宝宝吃的安全第一。还有一款国产的性价比更高，您需要的话我给您推荐。您看中了哪款告诉我~', '奶粉,产地,进口,新西兰', '奶粉产地与进口说明', 90
  UNION ALL SELECT 'baby_formula', '保质期到什么时候？还有多久', '亲，这款奶粉保质期到2027年3月，还有8个多月~奶粉开封后建议1个月内喝完，没开封的常温保存就行。这罐是全新未开封的，保质期很充足。宝宝喝得慢的话要算好时间，开封超1个月就不建议喝了，营养会流失还可能变质。我家宝宝转奶了才出的，罐身完好没有凹陷，您放心拍~', '奶粉,保质期,开封,保存', '奶粉保质期与保存说明', 89
  UNION ALL SELECT 'baby_formula', '是正品吗？支持验货吗', '亲，100%正品，支持扫码验真~罐底有防伪追溯码，可以在品牌官网或者微信公众号查验，能查到进口批次和检验检疫信息。宝宝入口的东西我不敢马虎，都是正规渠道进的货。如果您验出任何问题，无条件退款并承担来回运费。我家宝宝自己喝过的牌子，品质有保证，您放心拍下~', '奶粉,正品,防伪,验货', '奶粉正品承诺与验货说明', 94
  UNION ALL SELECT 'baby_formula', '奶粉开罐了吗？还剩多少', '亲，这罐开封了大概喝了三分之一，还剩三分之二~开封才一周，保存得很好，盖子每次都盖紧放在阴凉处，没有受潮结块。我家宝宝不爱喝这个味道要转奶了才出的。开封的奶粉建议1个月内喝完，您算下宝宝奶量，一个月内能喝完就没问题。价格比全新的便宜不少，性价比高，您考虑下~', '奶粉,开罐,剩余,保存', '奶粉开罐状态与剩余量', 86
  UNION ALL SELECT 'baby_formula', '这个米粉几个月宝宝能吃', '亲，这款米粉是2阶段的，适合6个月以上的宝宝~1阶段是4-6个月刚开始添加辅食的，2阶段是6-8个月，3阶段是8个月以上。辅食添加要循序渐进，从稀到稠从少到多。这款米粉是强化铁的，预防宝宝贫血。如果是刚开始加辅食建议选1阶段的原味米粉，更细腻好消化。您家宝宝几个月了？我帮您推荐合适的~', '米粉,辅食,月龄,阶段', '米粉适用月龄与阶段说明', 90
  UNION ALL SELECT 'baby_formula', '奶粉含糖吗？会不会太甜', '亲，这款奶粉不含蔗糖，是乳糖天然甜味~正规配方奶粉都不会加蔗糖，因为蔗糖容易导致宝宝龋齿和肥胖。奶粉的甜味来自乳糖，这是母乳里也有的天然糖，安全健康。如果尝起来特别甜就要警惕了，可能加了蔗糖。这款是正规品牌配方，配料表清楚标明，您放心。宝宝喝的奶粉选无蔗糖配方的最好~', '奶粉,含糖,蔗糖,乳糖', '奶粉含糖与甜味说明', 91
  UNION ALL SELECT 'baby_formula', '辅食果泥有添加剂吗？纯天然吗', '亲，这款果泥是0添加的，没有防腐剂香精色素~配料表只有水果和少量维生素C（抗氧化），非常干净。宝宝吃的辅食一定要选无添加的，乱七八糟的添加剂对宝宝发育不好。这款是正规大品牌，有质检报告，安全放心。开封后要冷藏24小时内喝完。我家宝宝吃了几罐才出的，品质有保证~', '果泥,辅食,添加剂,天然', '果泥添加剂与成分说明', 90
  UNION ALL SELECT 'baby_formula', '奶粉为什么出？宝宝不喝吗', '亲，是因为宝宝转奶了才出的~之前一直喝这款挺好的，后来医生建议换部分水解配方的，这款就不喝了。还剩一罐全新的没开封，保质期还长，出掉不浪费。这款奶粉营养全面宝宝消化吸收也好，只是我家宝宝特殊需要才转的。正品行货支持验真，您宝宝如果喝这款正合适，价格比专柜便宜不少~', '奶粉,转奶,原因,出物', '奶粉出物原因说明', 88
  UNION ALL SELECT 'baby_formula', '这个段数能换着喝吗？要转奶吗', '亲，不同段数不能直接换，需要转奶过渡~段数配方不同，直接换可能导致宝宝肠胃不适腹泻。转奶方法是：新旧奶粉混合，新奶粉比例从1/4逐渐增加到全部，大概7-10天过渡完成。如果宝宝适应好可以快一点，不适应就慢一点。转奶期间观察宝宝大便和精神状态。这款是2段，您宝宝满6个月了就可以从1段转到2段~', '奶粉,段数,转奶,过渡', '奶粉段数转换与转奶方法', 92
  UNION ALL SELECT 'baby_formula', '米粉冲泡会结块吗？好化开吗', '亲，这款米粉很细，冲泡不容易结块~关键是要用温开水（60-70度）先倒水再加米粉，边加边搅拌，这样最均匀。如果用太热的水会结块，太凉又化不开。第一次冲要稀一点，像米汤一样，宝宝适应后再慢慢加稠。这款米粉粉质细腻，搅拌几下就化了，比一些便宜牌子好冲很多。我家宝宝吃了好几盒，品质不错~', '米粉,冲泡,结块,化开', '米粉冲泡方法与注意事项', 88
  UNION ALL SELECT 'baby_formula', '奶粉罐有凹陷吗？包装完好吗', '亲，罐身完好没有凹陷，包装很完整~我发货前都会检查罐身，有凹陷的不会发。奶粉罐如果凹陷严重可能影响密封性，所以要注意。这款原箱发货，外包装箱和内罐都完好。我家宝宝自己喝的，囤的货，质量有保证。您收到后检查下罐身和塑封，完好再签收。有问题随时找我处理，您放心拍~', '奶粉,罐身,凹陷,包装', '奶粉罐身与包装说明', 87
  UNION ALL SELECT 'baby_formula', '果泥开封能放多久？要冷藏吗', '亲，果泥开封后必须冷藏，24小时内喝完~没开封的常温保存就行，开封后接触空气容易滋生细菌，宝宝肠胃娇嫩不能喝放久的。如果是吸嘴袋装的，宝宝喝剩下的也不能留到下一顿，要倒掉。这款果泥一瓶120ml，一顿喝完刚好。我家宝宝吃了几罐，品质不错才出的，价格比专柜便宜，您看中了就拍下~', '果泥,开封,冷藏,保存', '果泥开封保存与保质说明', 89
  UNION ALL SELECT 'baby_formula', '这个配方接近母乳吗？好消化吗', '亲，这款奶粉配方是模拟母乳设计的，添加了OPO结构脂和益生菌，比较接近母乳好消化~OPO结构脂能促进钙质吸收减少便秘，益生菌帮助肠道健康。没有一款奶粉能完全等同母乳，但这款算是配方比较接近的。宝宝喝了不上火不便秘，大便也正常。我家宝宝喝了半年消化吸收不错，转奶才出的。您宝宝如果消化不好可以试试这款~', '奶粉,配方,母乳,消化', '奶粉配方与消化性说明', 91
  UNION ALL SELECT 'baby_formula', '奶粉是羊奶还是牛奶？哪个不上火', '亲，这款是牛奶粉，羊奶粉我也有一款可以推荐~羊奶比牛奶分子小，更好消化吸收，不容易上火和过敏，但价格贵不少。牛奶粉性价比高，大多数宝宝喝着也没问题。如果宝宝对牛奶蛋白过敏或者容易上火，选羊奶粉更好。如果没有这些问题，牛奶粉就够了。您家宝宝什么情况？我帮您推荐合适的~', '奶粉,羊奶,牛奶,上火', '羊奶牛奶奶粉对比说明', 90
  UNION ALL SELECT 'baby_formula', '辅食是几阶段的？几个月开始吃', '亲，这款辅食米粉是2阶段的，适合6-8个月宝宝~辅食添加一般4-6个月开始，从1阶段原味米粉开始。2阶段可以加蔬菜水果口味了，3阶段8个月以上可以加肉泥和颗粒感食物。每个宝宝发育不同，看宝宝能坐稳、对食物感兴趣、挺舌反射消失了就可以加了。不能太早加辅食，4个月前宝宝的肠胃还消化不了~', '辅食,阶段,月龄,添加', '辅食阶段与添加月龄', 90
  UNION ALL SELECT 'baby_formula', '奶粉勺还在吗？刻度准吗', '亲，奶粉勺在的，就在罐里，刮平一勺约4.3g奶粉~冲调比例是一勺奶粉兑30ml水，罐身上有说明。奶粉勺要每次用完放回罐里保持干燥，不要用手直接抓勺子，不卫生。冲奶时先放水后放奶粉，水温40-50度最合适，太热会破坏营养。这款是正品，勺子和包装都是原装的，您放心使用~', '奶粉,奶粉勺,刻度,冲调', '奶粉勺与冲调比例说明', 87
  UNION ALL SELECT 'baby_formula', '这个面条含盐吗？1岁宝宝能吃吗', '亲，这款宝宝面条是无盐配方的，1岁宝宝能吃~1岁以内的宝宝不能吃盐，会增加肾脏负担。这款是专为婴幼儿设计的，无盐无添加，只有面粉和少量营养素。大人吃的面条含盐不能给宝宝吃。这款面条煮起来很软烂，好消化。我家宝宝吃了几包，品质不错。您宝宝1岁吃这个正合适，价格比专柜便宜~', '面条,辅食,含盐,1岁', '宝宝面条含盐与适用说明', 91
  UNION ALL SELECT 'baby_formula', '奶粉存放在哪了？没受潮吧', '亲，奶粉一直放在阴凉干燥的柜子里，没有受潮~存放奶粉要注意：常温阴凉处，避免阳光直射和高温；不要放冰箱，冰箱湿度大会受潮结块；每次取完盖紧盖子。这款保存得很好，粉质干燥松散没有结块。开封的奶粉1个月内喝完最好。我家宝宝转奶才出的，品质有保证，您放心拍下~', '奶粉,存放,受潮,保存', '奶粉存放与防潮说明', 88
  UNION ALL SELECT 'baby_formula', '果泥是进口品牌吗？有认证吗', '亲，这款果泥是法国进口品牌，有海关检验检疫证明和中文标签~进口辅食都经过严格检验，比一些小作坊的国产辅食安全。这款是无添加配方，配料表只有水果和维C，干净安全。有质检报告，支持查验。我家宝宝吃了几罐消化好才推荐的，价格比专柜便宜不少。宝宝吃的安全第一，您放心拍下~', '果泥,进口,品牌,认证', '果泥品牌与认证说明', 89
  UNION ALL SELECT 'baby_formula', '奶粉有防伪吗？怎么查真伪', '亲，这款奶粉有防伪追溯码，在罐底~查询方式有三种：1、扫罐底二维码直接查；2、去品牌官网输入防伪码查；3、打品牌客服电话查。能查到生产批次、进口时间、检验检疫信息。建议您收到后第一时间查验，真伪一目了然。宝宝入口的东西马虎不得，我这边都是正规渠道正品，支持任何方式验真，您放心拍下~', '奶粉,防伪,真伪,追溯', '奶粉防伪与真伪查验', 94
  UNION ALL SELECT 'baby_formula', '米粉含铁吗？预防贫血吗', '亲，这款米粉是强化铁配方的，能有效预防宝宝缺铁性贫血~6个月后宝宝体内储存的铁消耗得差不多了，母乳中铁含量又低，所以辅食补铁很重要。这款米粉每100g含铁6mg以上，符合国标。强化铁米粉是宝宝第一口辅食的首选。原味的更好，不容易过敏。我家宝宝吃了好几盒，血红蛋白一直正常，品质不错~', '米粉,铁,贫血,强化', '米粉含铁与预防贫血说明', 91
  UNION ALL SELECT 'baby_formula', '这个奶粉乳糖不耐受宝宝能喝吗', '亲，这款是普通配方奶粉，乳糖不耐受宝宝不能喝~乳糖不耐受的宝宝要选无乳糖或者低乳糖配方的特殊奶粉。普通奶粉里有乳糖，乳糖不耐受的宝宝喝了会腹泻胀气。如果您宝宝确诊乳糖不耐受，我给您推荐无乳糖配方的款。不确定的话建议先咨询医生。宝宝肠胃问题要重视，选对奶粉很重要~', '奶粉,乳糖,不耐受,腹泻', '奶粉乳糖不耐受说明', 92
  UNION ALL SELECT 'baby_formula', '辅食可以退款吗？宝宝不爱吃怎么办', '亲，辅食开封后不支持退款哦，食品安全规定~没开封的如果不喜欢可以7天内退换。建议您先买一罐试试，宝宝爱吃再多买。每个宝宝口味不同，有的爱吃有的不爱吃。如果宝宝不爱吃，可以混在米粉或者粥里试试。我家宝宝之前不爱吃纯果泥，混米粉里就吃了。您先少买点试，省得浪费~', '辅食,退款,不爱吃,试吃', '辅食退款政策与建议', 85
  UNION ALL SELECT 'baby_formula', '奶粉是新西兰进口的吗？有溯源吗', '亲，这款是新西兰原装进口的，有完整溯源~罐底有二维码，扫码能看到：奶源牧场、生产工厂、出口检验、进口报关、检验检疫全流程信息。新西兰奶粉监管很严，品质有保障。这款是正品行货，中文标签齐全，支持任何方式验真。我家宝宝喝了大半年，消化吸收都不错，转奶才出的。您放心拍下，宝宝吃的安全第一~', '奶粉,新西兰,溯源,进口', '奶粉新西兰进口与溯源', 93
  UNION ALL SELECT 'baby_formula', '果泥含糖吗？会不会蛀牙', '亲，这款果泥不含添加糖，甜味是水果天然的果糖~没有蔗糖白砂糖等添加糖，不会导致蛀牙。果糖是水果天然存在的，适量没问题。不过喝完果泥建议给宝宝喝口水或者刷牙，保护口腔。1岁以内不要吃添加糖，1-3岁也要控制。这款是无添加配方的，配料表只有水果和维C，安全放心~', '果泥,含糖,蛀牙,果糖', '果泥含糖与蛀牙说明', 89
  UNION ALL SELECT 'baby_formula', '奶粉冲调比例多少？一勺多少水', '亲，这款奶粉冲调比例是一平勺奶粉（约4.3g）兑30ml温开水~冲奶步骤：先放水后放奶粉，水温40-50度，摇匀就行。不要用开水，会破坏营养；也不要用矿泉水，矿物质太多宝宝肾脏负担重，用白开水最好。冲好的奶常温下2小时内喝完，喝剩的不能留下一顿。奶粉罐上有详细说明，您按比例冲就行。宝宝喝的奶要现冲现喝~', '奶粉,冲调,比例,一勺', '奶粉冲调比例与方法', 90
  UNION ALL SELECT 'baby_formula', '这个肉泥几个月宝宝吃？含盐吗', '亲，这款肉泥适合7个月以上宝宝吃，无盐配方~7个月开始可以加肉泥补铁补蛋白了，从鸡肉猪肉开始，慢慢加牛肉鱼虾。这款是无盐无添加的，只有肉和少量水，安全。1岁以内绝对不能加盐，宝宝肾脏发育不完善。这款肉泥很细腻，刚开始添加辅食的宝宝也好消化。我家宝宝吃了几罐不错，价格比专柜便宜~', '肉泥,辅食,含盐,月龄', '肉泥月龄与含盐说明', 90
  UNION ALL SELECT 'baby_formula', '奶粉开了几个月了？还能喝吗', '亲，这罐开封才5天，还在1个月安全期内~开封的奶粉建议1个月内喝完，超过1个月营养流失还可能变质，不建议给宝宝喝。这罐开封5天，保存得很好，盖子每次盖紧放阴凉处，没有受潮结块。我家宝宝转奶才出的，还剩大半罐。您算下宝宝奶量，1个月内能喝完就放心拍，价格比全新的便宜不少~', '奶粉,开封,几个月,保质', '奶粉开封时长与安全性', 87
  UNION ALL SELECT 'baby_formula', '辅食一套出吗？还是单卖', '亲，辅食可以单买也可以一套出，一套买更划算~我有米粉、果泥、肉泥、面条几种，您按需要选。建议刚开始加辅食先买米粉试，宝宝适应了再加果泥肉泥。一套买我给优惠价，比单买便宜。每种口味先买一罐试，宝宝爱吃再多囤。宝宝口味会变，囤太多可能浪费。您告诉我要哪些我帮您配，有问题随时找我~', '辅食,一套,单卖,搭配', '辅食套装与单卖说明', 86
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 2. baby_diaper（纸尿裤）- 30 条
-- ============================================================================
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.55', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'baby_diaper' AS code, '这个纸尿裤是什么码的？多大宝宝用' AS question, '亲，这款是L码的，适合9-14kg的宝宝~一般6-12个月宝宝穿L码。尺码选择主要看体重不是月龄，不同牌子尺码有差异。如果宝宝在两个码之间，建议选大一码，宽松点比勒着好。穿太小会勒腿漏尿，太大会侧漏。您告诉我宝宝体重我帮您推荐合适的码。这款囤多了才出，正品行货，您放心~' AS answer, '纸尿裤,尺码,L码,体重' AS tags, '纸尿裤尺码与适用体重' AS source_summary, 91 AS score
  UNION ALL SELECT 'baby_diaper', 'NB/S/M/L/XL 分别多大体重用', '亲，各码适用体重参考：NB码5kg以下（新生儿），S码4-8kg，M码6-11kg，L码9-14kg，XL码12-17kg，XXL码15kg以上~不同牌子略有差异，以包装说明为准。选码主要看体重，体重在两个码之间选大一码。要注意宝宝胖瘦也有影响，胖宝宝特别是大腿粗的要选大一码，不然勒腿。您告诉我宝宝体重和月龄，我帮您选最合适的码~', '纸尿裤,尺码,体重,NB,XL', '纸尿裤各码体重对照说明', 93
  UNION ALL SELECT 'baby_diaper', '透气吗？会不会红屁股', '亲，这款纸尿裤透气性很好，不容易红屁股~红屁股主要是因为尿尿便便刺激皮肤和闷热造成的。这款有透气底层和3D凸起表层，能减少皮肤接触湿气。但再好的纸尿裤也要勤换，2-3小时换一次，拉了便便马上换。每次换的时候洗洗屁股晾干再穿。配合护臀膏用更好。我家宝宝用这款没有红屁股，囤多了才出的~', '纸尿裤,透气,红屁股,勤换', '纸尿裤透气与红屁股预防', 92
  UNION ALL SELECT 'baby_diaper', '是正品吗？怎么辨别真假', '亲，100%正品，支持验真~辨别真假几个方法：1、看包装印刷清晰度，假货印刷模糊有重影；2、看防伪码，正品有防伪码可查；3、摸材质，正品柔软细腻假货粗糙；4、闻味道，正品无异味假货有刺鼻味。这款是正规渠道进的货，有进货凭证，支持任何方式验真。宝宝贴身用的东西安全第一，我不卖假货砸招牌，您放心拍下~', '纸尿裤,正品,真假,辨别', '纸尿裤正品与真假辨别', 94
  UNION ALL SELECT 'baby_diaper', '一包多少片？够用几天', '亲，这款L码一包56片，按2-3小时换一次，大概够用4-5天~新生儿换得勤一天10-12片，大宝宝一天6-8片。囤货建议按月囤，一个月大概4-6包L码。买多了不如少量多次买，纸尿裤有保质期，放久了吸水性会下降。这款我囤多了宝宝长得快用不上XL才出的，正品行货，价格比专柜便宜不少~', '纸尿裤,一包,多少片,几天', '纸尿裤每包片数与用量', 89
  UNION ALL SELECT 'baby_diaper', '拉拉裤和纸尿裤区别？哪个好', '亲，拉拉裤和纸尿裤区别在于穿脱方式~纸尿裤是躺着一贴就穿，适合小宝宝不会站的；拉拉裤像小内裤一样套着穿，适合会站会走的宝宝，站着就能换不用躺。拉拉裤穿脱方便但价格贵一点。一般6个月前用纸尿裤，7个月会翻了可以换拉拉裤。晚上建议用纸尿裤吸收量大不侧漏。我家两种都用过，各有好处，您按宝宝月龄选~', '拉拉裤,纸尿裤,区别,选择', '拉拉裤与纸尿裤对比', 90
  UNION ALL SELECT 'baby_diaper', '厚吗？夏天用会不会闷', '亲，这款是薄款透气的，夏天用不闷~纸尿裤厚薄影响透气性，薄款更透气但吸收量小些，厚款吸收大但闷热。夏天选薄款不容易红屁股，勤换就行。冬天可以选厚款吸收大过夜不漏。这款薄款适合春夏秋，夏天注意2小时换一次配合护臀膏。我家宝宝夏天用这款没红过屁股，囤多了才出的，价格很实惠~', '纸尿裤,厚薄,夏天,闷热', '纸尿裤厚薄与季节适用', 88
  UNION ALL SELECT 'baby_diaper', '纸尿裤为什么出？买多了吗', '亲，是囤多了宝宝长得快用不上了~之前做活动囤了好几包L码，结果宝宝长得快2个月就穿不下L码要换XL了。全新未开封，正品行货，保质期还长。这种囤多用不上的情况很常见，宝宝长得快码数变化大。所以建议纸尿裤不要囤太多，一个月一买最好。这款价格比专柜便宜不少，您宝宝正好穿L码的话很划算~', '纸尿裤,囤多,出物,长得快', '纸尿裤出物原因说明', 87
  UNION ALL SELECT 'baby_diaper', '这个码偏大偏小吗？怎么选', '亲，这款尺码标准不偏大不偏小~不同牌子尺码有差异，有的偏大有的偏小。这款按标准体重选就行。如果您家宝宝偏胖，大腿粗，建议选大一码，不然勒腿会留印子。偏瘦的宝宝按标准选就行。买之前量下宝宝体重和大腿围最准。不确定的话先买小包试，合适再多买。我家宝宝穿这款正合适，囤多了才出的~', '纸尿裤,尺码,偏大,偏小', '纸尿裤尺码偏码与选择', 89
  UNION ALL SELECT 'baby_diaper', '有漏尿情况吗？吸收怎么样', '亲，这款吸收力很好，不漏尿~吸收力取决于高分子吸水珠的量和表层设计。这款有3D导流层能快速分散尿液，吸水珠吸收量大锁水好。正常2-3小时换一次不会漏。晚上如果睡得久可以选夜用款吸收更大。漏尿一般是因为尺码不对或者穿的位置不对，穿的时候把大腿防漏侧边拨出来就不会漏。我家宝宝用这款没漏过，囤多了才出~', '纸尿裤,漏尿,吸收,防漏', '纸尿裤吸收与防漏说明', 90
  UNION ALL SELECT 'baby_diaper', '是男宝还是女宝款？有区别吗', '亲，纸尿裤大部分是不分男女的通用款~少数牌子有男宝女宝专用款，男宝前厚后薄，女宝前后均匀。但差别不大，通用款完全够用。这款是通用款，男女宝都能用。选纸尿裤主要看尺码和吸收力，不用纠结男女款。我家是男宝用的，但通用款无所谓。正品行货，价格很实惠，您看中了就拍下~', '纸尿裤,男宝,女宝,通用', '纸尿裤男女款区别说明', 86
  UNION ALL SELECT 'baby_diaper', '纸尿裤临期吗？保质期到什么时候', '亲，这款保质期还有2年多，不临期~纸尿裤保质期一般3年，这款到2028年5月，还很新。纸尿裤放久了吸水性会下降，建议买新鲜的。临期的虽然便宜但吸水差，不建议买。这款是新鲜批次，囤多了才出，价格比专柜便宜。您买的时候看下包装上的生产日期和保质期就行。我家宝宝穿不上这码了才出的，您放心拍~', '纸尿裤,临期,保质期,新鲜', '纸尿裤保质期与临期说明', 88
  UNION ALL SELECT 'baby_diaper', '这个牌子好用吗？会不会过敏', '亲，这个牌子是大品牌，好用不容易过敏~我家宝宝用了大半年没有过敏红屁股。纸尿裤过敏一般是材料问题或者香精刺激，这款无香精无刺激，材料柔软亲肤。如果宝宝是敏感肌容易过敏，可以先买小包试。每个宝宝肤质不同，别人不过敏的不代表您宝宝不过敏，试了才知道。这款总体口碑很好，正品行货，您放心尝试~', '纸尿裤,牌子,过敏,敏感', '纸尿裤品牌与过敏说明', 89
  UNION ALL SELECT 'baby_diaper', '拉拉裤好穿脱吗？学步宝宝用方便吗', '亲，拉拉裤特别适合学步宝宝，站着就能换~拉拉裤像小内裤一样往上一拉就穿好，不用躺着贴魔术贴，宝宝会翻会爬以后躺着换太难了，拉拉裤就很方便。脱的时候从侧面撕开一扯就下来。学步期的宝宝强烈推荐拉拉裤。这款拉拉裤弹力好不勒肚肚，我家宝宝学步期用的，囤多了才出。您宝宝会翻了就可以换拉拉裤了~', '拉拉裤,学步,穿脱,方便', '拉拉裤学步期便利说明', 90
  UNION ALL SELECT 'baby_diaper', '纸尿裤魔术贴粘得牢吗？会开吗', '亲，这款魔术贴粘得很牢，正常活动不会开~魔术贴是反复粘贴的，可以调整松紧。穿的时候贴紧一点，留两指宽的空隙不勒肚肚就行。如果宝宝特别好动，可以选拉拉裤不存在魔术贴开的问题。这款魔术贴粘性很好，我家宝宝用着没开过。正品行货，囤多了才出，价格很实惠，您看中了就拍下~', '纸尿裤,魔术贴,粘牢,开', '纸尿裤魔术贴粘性说明', 86
  UNION ALL SELECT 'baby_diaper', '一晚用一片够吗？夜里要换吗', '亲，要看宝宝月龄和尿量~新生儿夜里要换2-3次，6个月后夜奶少了可以少换。1岁后大部分宝宝一晚1片夜用就够了，如果尿量大可以中途换一次。这款是日用款，夜用建议选吸收量大的夜用款或者拉拉裤。我家宝宝1岁后一晚1片夜用不漏。您看宝宝月龄和尿量决定，如果早上起来纸尿裤鼓得很大就要换更厚的~', '纸尿裤,晚上,一夜,换', '纸尿裤夜间使用与更换', 88
  UNION ALL SELECT 'baby_diaper', '这个码我家宝宝14斤能用吗', '亲，14斤大概7kg，按体重选M码比较合适（6-11kg）~L码是9-14kg，14斤7kg穿L码会偏大容易侧漏。建议您选M码。不过要看宝宝胖瘦，如果特别胖大腿粗可以选L码。最准确的方法是量体重和大腿围。我店里M码也有，您需要的话我给您发链接。选对码不漏尿不勒腿最重要，别贪大~', '纸尿裤,14斤,尺码,选择', '纸尿裤按体重选码说明', 90
  UNION ALL SELECT 'baby_diaper', '纸尿裤薄款还是厚款？季节用', '亲，这款是薄款，适合春夏秋三季~薄款透气不闷不容易红屁股，但吸收量小些要勤换。冬天可以选厚款吸收大过夜不漏。其实薄厚各有优势，夏天薄款勤换最好，冬天厚款过夜好。这款薄款夏天用很好，2小时换一次配合护臀膏。我家宝宝夏天用的这款没红屁股，囤多了才出，价格很实惠。您按季节选合适的款~', '纸尿裤,薄款,厚款,季节', '纸尿裤薄厚与季节选择', 87
  UNION ALL SELECT 'baby_diaper', '吸水珠会漏出来吗？安全吗', '亲，这款吸水珠不会漏出来，安全~吸水珠是高分子树脂（SAP），在纸尿裤芯体里被封住，正常穿不会漏。如果纸尿裤破损或者宝宝撕开才会漏出来。SAP是安全的，无毒无刺激，就算少量接触皮肤也没事。这款是正品，芯体封合牢固，不会漏珠。我家宝宝用了大半年没出现过漏珠，正品行货您放心~', '纸尿裤,吸水珠,SAP,安全', '纸尿裤吸水珠安全性说明', 89
  UNION ALL SELECT 'baby_diaper', '拉拉裤腰围弹力大吗？胖宝宝能穿吗', '亲，这款拉拉裤腰围弹力很大，胖宝宝也能穿~腰围用的是高弹力氨纶，能拉伸很大不勒肚肚。我家宝宝比较胖，穿这款不勒腰没有印子。如果宝宝特别胖超重了，建议选大一码更舒服。拉拉裤比纸尿裤腰围弹力好，胖宝宝穿拉拉裤更舒服。这款囤多了才出，正品行货，价格很实惠，您宝宝胖的话选这款准没错~', '拉拉裤,腰围,弹力,胖宝宝', '拉拉裤腰围弹力与胖宝宝', 88
  UNION ALL SELECT 'baby_diaper', '纸尿裤是日本进口的吗？花王吗', '亲，这款是日本花王进口版的，不是国产花王~日本版和国产版区别：日本版更薄更软但价格贵，国产版厚一点吸收大价格便宜。两个都是正品花王，配方工艺略有不同。日本版适合夏天，国产版适合冬天。这款日本版囤多了才出，价格比代购便宜。如果您要国产版我也有，更便宜。您按需要选，都是正品行货~', '纸尿裤,花王,日本,进口', '纸尿裤花王日本版说明', 90
  UNION ALL SELECT 'baby_diaper', '这个牌子跟帮宝适比怎么样', '亲，这个牌子和帮宝适各有优势~帮宝适一线大牌品质稳定但贵，这款性价比高便宜不少。吸收力帮宝适略好，柔软度差不多。如果预算充足选帮宝适，追求性价比选这款。其实大品牌纸尿裤品质都不差太多，关键看适不适合宝宝，有的宝宝用A牌子红屁股换B牌子就好了。建议先买小包试，合适再多买。这款我家宝宝用着不错，囤多了才出~', '纸尿裤,帮宝适,对比,牌子', '纸尿裤品牌对比说明', 87
  UNION ALL SELECT 'baby_diaper', '纸尿裤包装开封了吗？还剩多少', '亲，这包开封了用了几片，还剩大概50片（原56片）~开封要密封好防潮，可以用夹子夹住或者放密封袋。开封后尽快用完，放久了吸水性下降。这款是囤多了用不上，开封试了几片发现宝宝穿不上这码了才出的。价格比全新的便宜不少，剩余量大很划算。您算下宝宝用量，1-2周内用完最好~', '纸尿裤,开封,剩余,用量', '纸尿裤开封状态与剩余量', 86
  UNION ALL SELECT 'baby_diaper', '有尿显吗？湿了会变色吗', '亲，这款有尿显的，湿了会变色~尿显是纸尿裤外面的两条线，干了是黄色，湿了变蓝色/绿色，一眼就能看出该换了。很方便不用每次打开看。尿显变色说明尿量差不多了该换，不要等尿显全变色才换，2-3小时就该换。这款尿显很灵敏，我家宝宝用着很方便。正品行货，囤多了才出，价格很实惠，您看中了就拍下~', '纸尿裤,尿显,变色,方便', '纸尿裤尿显功能说明', 88
  UNION ALL SELECT 'baby_diaper', '这个码囤多了宝宝长得快用不上了', '亲，是的囤多了宝宝长得快就穿不上了，所以出掉~宝宝前半年长得快，可能1-2个月就要换码。建议纸尿裤一次买1-2个月用量就好，别囤太多。我之前做活动囤了好多L码，结果宝宝2个月就穿XL了，L码就用不上了。全新未开封，正品行货，价格比专柜便宜不少。您宝宝正好穿L码的话很划算，用完别再囤太多~', '纸尿裤,囤多,长得快,换码', '纸尿裤囤货与换码说明', 87
  UNION ALL SELECT 'baby_diaper', '纸尿裤柔软吗？会不会磨大腿', '亲，这款很柔软，不会磨大腿~表层是无纺布的，摸着很柔软亲肤。大腿防漏侧边也是柔软的，不会勒不会磨。如果纸尿裤粗糙或者侧边硬，宝宝动来动去会磨红大腿根。这款材料柔软，我家宝宝用着没有磨红过。选纸尿裤摸一下表层和侧边，柔软的才好。正品行货，囤多了才出，价格很实惠，您看中了就拍下~', '纸尿裤,柔软,磨大腿,侧边', '纸尿裤柔软度与防磨说明', 88
  UNION ALL SELECT 'baby_diaper', '拉拉裤撕开方便吗？换的时候', '亲，拉拉裤侧面有撕开线，一撕就开，换的时候很方便~穿的时候像内裤套上去，脱的时候从侧面撕开线撕开扯下来就行，不用整条脱。特别适合大便了的情况，撕开扯下来不会弄脏宝宝腿。比纸尿裤脱起来方便多了。这款拉拉裤撕开线设计很好，一撕就开不费力。我家宝宝学步期用的，囤多了才出，价格很实惠~', '拉拉裤,撕开,方便,更换', '拉拉裤撕开与更换便利', 89
  UNION ALL SELECT 'baby_diaper', '纸尿裤透气孔明显吗？防红臀吗', '亲，这款纸尿裤底层有透气微孔，防红臀效果好~透气孔让湿气能散发出去，减少皮肤闷湿。配合3D凸起表层减少皮肤接触面积，不容易红屁股。但再透气也要勤换，2-3小时一次，便便马上换。每次换洗洗晾干涂护臀膏。我家宝宝用这款没红过屁股。正品行货，囤多了才出，价格很实惠。预防红臀关键是勤换+透气+护臀膏~', '纸尿裤,透气孔,红臀,预防', '纸尿裤透气孔与防红臀', 89
  UNION ALL SELECT 'baby_diaper', '这个 NB 码新生儿用会太大吗', '亲，NB码就是新生儿码，不会太大~NB码适合5kg以下新生儿，刚出生的宝宝用NB码正好。如果宝宝出生体重比较大（超过4kg），可以直接用S码。一般满月前用NB码，满月后换S码。NB码不用囤太多，宝宝长得快一个月就换码了，囤2-3包够了。这款NB码全新未开封，正品行货，我家宝宝用不上了才出的，价格很实惠~', '纸尿裤,NB,新生儿,尺码', 'NB码新生儿适用说明', 90
  UNION ALL SELECT 'baby_diaper', '纸尿裤产地是哪？国产版还是进口版', '亲，这款是国产版的，不是进口版~国产版和进口版区别：国产版在国内工厂生产，性价比高货源稳定；进口版原装进口，更薄更软但贵。两个都是正品，品质都达标。国产版适合日常用，进口版适合追求更好的。这款国产版性价比很高，价格比进口版便宜三分之一。我家宝宝用国产版挺好的，囤多了才出。您要进口版我也有，看您需要~', '纸尿裤,产地,国产,进口', '纸尿裤国产进口版说明', 88
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 3. baby_toys（玩具书籍）- 30 条
-- ============================================================================
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.55', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'baby_toys' AS code, '这个玩具适合多大宝宝？几个月能玩' AS question, '亲，这款摇铃适合3个月以上宝宝~不同玩具适合不同月龄：0-3个月看黑白卡、听音乐；3-6个月摇铃、牙胶；6-12个月积木、敲打玩具；1-2岁拼图、绘本。选玩具一定要按月龄，太小的玩具大宝宝没兴趣，太复杂的玩具小宝宝玩不了还可能有安全隐患。您家宝宝几个月了？我帮您推荐合适的玩具~' AS answer, '玩具,月龄,几个月,适合' AS tags, '玩具适用月龄说明' AS source_summary, 92 AS score
  UNION ALL SELECT 'baby_toys', '材质安全吗？会咬会不会有毒', '亲，这款玩具是食品级硅胶的，宝宝咬也没毒~宝宝玩具一定要选安全材质，因为宝宝啥都往嘴里放。硅胶、PP、ABS这些食品级材质是安全的。便宜的劣质塑料可能有BPA和塑化剂，对宝宝有害。这款有3C认证，材质达标安全。但玩具毕竟不是食物，还是要引导宝宝不要长期咬。我家宝宝玩的，安全第一才推荐的，您放心拍下~', '玩具,材质,安全,咬', '玩具材质安全性与认证', 93
  UNION ALL SELECT 'baby_toys', '积木有毛刺吗？会扎手吗', '亲，这款积木是水性环保漆打磨光滑，没有毛刺不扎手~木质玩具最怕有毛刺扎到宝宝，这款每一块都打磨得很光滑，边角也是圆角处理。漆是水性环保漆无毒无味，宝宝咬了也没事。买木质玩具一定要检查毛刺和漆面，劣质的毛刺多漆还掉色。这款是正规品牌，品质有保证。我家宝宝玩了大半年，成色8成新，换了大积木才出~', '积木,毛刺,扎手,环保漆', '积木毛刺与漆面安全说明', 90
  UNION ALL SELECT 'baby_toys', '绘本是正版的吗？印刷清晰吗', '亲，这款绘本是正版授权的，印刷清晰色彩还原好~正版绘本印刷精美纸张好，色彩鲜艳不伤眼。盗版绘本印刷模糊颜色暗淡，还可能用劣质油墨有异味对宝宝健康不好。宝宝绘本一定要买正版，毕竟宝宝会翻会咬。这款是正规出版社正版，有ISBN编号可以查。我家宝宝看了几遍，成色很新，价格比书店便宜不少，您放心拍下~', '绘本,正版,印刷,清晰', '绘本正版与印刷质量说明', 92
  UNION ALL SELECT 'baby_toys', '玩具有小零件吗？宝宝会吞吗', '亲，这款玩具是整件的没有小零件，3岁以下宝宝放心玩~3岁以下宝宝玩的玩具不能有小零件，因为宝宝会往嘴里放，小零件有吞咽窒息危险。选玩具看包装上的年龄标识，3岁以下选大件无小零件的。这款是适合1岁宝宝的，整件大块没有小零件。我家宝宝玩了没问题，换了大玩具才出。您买玩具一定注意小零件问题，安全第一~', '玩具,小零件,吞咽,安全', '玩具小零件与吞咽安全', 94
  UNION ALL SELECT 'baby_toys', '这个早教机有声音吗？音量大吗', '亲，这款早教机有声音，音量可以调节~有3档音量可调，最低档很轻柔不刺耳，最高档也不算吵。宝宝听力娇嫩，音量不要太大，建议用中低档。这款早教机内容丰富，有儿歌、故事、古诗、英语，还能插TF卡自己加内容。音质清晰不刺耳。我家宝宝听了大半年，成色很新，换了大屏早教机才出，价格很实惠~', '早教机,音量,声音,调节', '早教机音量与功能说明', 89
  UNION ALL SELECT 'baby_toys', '拼图几块的？多大宝宝能拼', '亲，这款拼图是6块的，适合2-3岁宝宝~拼图块数要和宝宝年龄匹配：1-2岁玩4块嵌入拼图，2-3岁玩6-12块，3-4岁玩20-30块，4岁以上可以玩50块以上。太难了宝宝挫败感强，太简单了没挑战。这款6块的2岁宝宝刚好，有底板对照好拼。我家宝宝2岁多玩的，成色很新，玩腻了才出。您家宝宝几岁？我帮您推荐合适块数的~', '拼图,块数,年龄,适合', '拼图块数与适用年龄', 90
  UNION ALL SELECT 'baby_toys', '玩具几成新？有使用痕迹吗', '亲，这款玩具9成新，有轻微使用痕迹但不明显~我家宝宝玩了2个月，保护得不错没有磕碰掉漆。我拍了多角度实物图您看过了，成色很好。宝宝玩具有点使用痕迹很正常，不影响使用。全新的贵很多，二手9成新的性价比高。如果您介意全新可以买新的，不介意的话这款很值。换了大玩具才出，价格比新的便宜不少~', '玩具,成色,使用痕迹,9成新', '玩具成色与使用痕迹', 87
  UNION ALL SELECT 'baby_toys', '绘本有几本？一套出吗', '亲，这套绘本是一套8本的，整套出更划算~单本也可以，但一套买我给优惠。8本涵盖了习惯养成、情绪管理、认知启蒙几个主题，适合1-3岁。绘本建议成套买，主题系统宝宝能学到更多。这套是正版，印刷精美。我家宝宝看了几遍，成色很新没有撕破。换了大绘本才出，价格比书店便宜不少。您看中了就拍下，有问题随时找我~', '绘本,一套,几本,套装', '绘本套装与单本说明', 88
  UNION ALL SELECT 'baby_toys', '玩具需要电池吗？带不带', '亲，这款玩具需要3节5号电池，不带的~因为电池是消耗品而且运输有规定，一般玩具都不带电池。您家里应该有5号电池，没有的话超市几块钱就能买。建议用碱性电池耐用，别用碳性电池容易漏液损坏玩具。不用的时候取出电池，防止漏液。这款玩具音效灯光效果需要电池，没有电池也能当普通玩具玩。我家宝宝玩的，成色很新~', '玩具,电池,5号,不带', '玩具电池与使用说明', 86
  UNION ALL SELECT 'baby_toys', '这个摇铃声音刺耳吗？会吓到宝宝吗', '亲，这款摇铃声音很轻柔，不会吓到宝宝~摇铃声音大小和设计有关，这款用的是内部小珠子，摇晃时声音清脆轻柔不刺耳。有些劣质摇铃声音又大又尖，会吓到宝宝。选摇铃要选声音轻柔的，宝宝听力娇嫩。这款我家宝宝3个月开始玩的，没有被吓到过。成色很新，宝宝长大不玩了才出，价格很实惠。您放心，声音很温柔~', '摇铃,声音,刺耳,吓到', '摇铃声音与宝宝听力', 90
  UNION ALL SELECT 'baby_toys', '积木是木头的还是塑料的？环保吗', '亲，这款积木是榉木的，环保安全~木质积木比塑料的有质感，榉木硬度高不掉木屑。漆是水性环保漆无毒无味，宝宝咬了也没事。塑料积木轻便耐摔但没木质有质感。两种各有优点。这款木质的打磨光滑无毛刺，我家宝宝玩了大半年，成色8成新，换了大积木才出。木质积木有3C认证，安全达标，您放心拍下~', '积木,木头,塑料,环保', '积木材质与环保说明', 89
  UNION ALL SELECT 'baby_toys', '绘本适合几岁？有拼音吗', '亲，这套绘本适合1-3岁，没有拼音~1-3岁的绘本主要是图画为主，字少，家长讲给宝宝听，不需要拼音。3岁以上开始识字了可以选有拼音的。这套是低幼绘本，图画大字少，适合亲子共读。每本一个主题，讲生活习惯、情绪认知。我家宝宝1岁多看的，成色很新。换了大绘本才出，价格比书店便宜。您宝宝几岁？我帮您推荐合适的~', '绘本,年龄,拼音,几岁', '绘本年龄与拼音说明', 88
  UNION ALL SELECT 'baby_toys', '玩具为什么出？宝宝玩腻了吗', '亲，是宝宝玩腻了换新的才出的~宝宝的注意力有限，一个玩具玩1-2个月就腻了，需要换新玩具刺激。这款玩具我家宝宝玩了2个月，现在不感兴趣了才出。玩具本身成色很好，功能正常，没有损坏。二手玩具性价比高，宝宝玩腻了出掉换新的，比一直买新的省很多。您看中了就拍下，有问题随时找我~', '玩具,出物,玩腻,换新', '玩具出物原因说明', 86
  UNION ALL SELECT 'baby_toys', '这个牙胶硅胶的吗？安全吗', '亲，这款牙胶是食品级液态硅胶的，安全~宝宝长牙期喜欢咬东西，牙胶能缓解牙龈不适。液态硅胶是食品级的，软硬适中，宝宝咬着舒服也不会伤牙龈。有3C认证，无BPA无塑化剂，宝宝放嘴里放心。这款可以高温水煮消毒。我家宝宝长牙期用的，成色很新，长完牙不咬了才出。宝宝入口的东西安全第一，正品行货您放心~', '牙胶,硅胶,安全,长牙', '牙胶硅胶材质与安全', 92
  UNION ALL SELECT 'baby_toys', '拼图缺件吗？完整吗', '亲，这款拼图我数过了，6块都在，完整不缺件~买二手拼图最怕缺件，我出之前特意数过确认完整。拼图缺一块就拼不了了，所以一定要确认。这款我家宝宝玩了2个月，每次玩完都收好没有丢。成色很新没有折痕。换了大拼图才出，价格很实惠。您收到后也可以数一下，6块都在才对，有问题随时找我~', '拼图,缺件,完整,6块', '拼图缺件与完整性说明', 90
  UNION ALL SELECT 'baby_toys', '早教机内容多吗？能联网吗', '亲，这款早教机内容挺多的，但不能联网~内置了儿歌、故事、古诗、英语、国学等内容，几百首够听了。不能联网下载，但可以插TF卡自己加内容。联网的早教机功能多但价格贵，这款不联网的性价比高。如果您要联网的我可以推荐。这款我家宝宝听了大半年，成色很新，换了大屏早教机才出，价格很实惠。您看中了就拍下~', '早教机,内容,联网,TF卡', '早教机内容与联网说明', 87
  UNION ALL SELECT 'baby_toys', '玩具能水洗吗？消毒方便吗', '亲，这款玩具可以水洗，消毒方便~塑料硅胶玩具可以用清水洗或者奶瓶清洗剂洗，然后开水烫一下消毒。木质玩具不能泡水，用湿布擦然后晾干。布艺玩具可以手洗。定期消毒很重要，宝宝玩具容易滋生细菌。这款塑料的可以水洗高温烫，消毒很方便。我家宝宝玩具我每周洗一次。成色很新，换了大玩具才出，价格很实惠~', '玩具,水洗,消毒,清洁', '玩具水洗与消毒说明', 89
  UNION ALL SELECT 'baby_toys', '这个布书会掉色吗？咬了安全吗', '亲，这款布书是活性印染的不掉色，咬了安全~布书就是给宝宝咬的，材质必须安全。这款用的是A类婴儿级面料，活性印染不掉色无毒。可以水洗，洗了不掉色不变形。布书适合0-1岁宝宝，有响纸、BB器、不同材质触感，刺激宝宝感官发育。我家宝宝小时候玩的，成色很新，长大了不感兴趣才出。宝宝入口的东西安全第一，正品行货~', '布书,掉色,咬,安全', '布书掉色与安全说明', 91
  UNION ALL SELECT 'baby_toys', '积木多少块？够宝宝搭吗', '亲，这款积木是50块的，够宝宝搭了~50块可以搭房子、桥、塔各种造型，1-3岁宝宝够玩。如果宝宝特别爱搭可以买100块的。块数太多收纳麻烦，太少又不够搭，50块刚好。这款是榉木的，打磨光滑无毛刺，水性漆环保。我家宝宝玩了大半年，成色8成新，换了大积木才出。您宝宝几岁？我帮您推荐合适的块数~', '积木,块数,50块,搭', '积木块数与搭建说明', 88
  UNION ALL SELECT 'baby_toys', '绘本是英文还是中文的？能点读吗', '亲，这套绘本是中文的，不能点读~中文绘本适合家长讲给宝宝听，亲子共读。如果您要英文绘本或者点读版的我可以推荐。点读绘本需要配点读笔，能发声但贵一些。这套中文绘本性价比高，图画精美字少，适合1-3岁亲子共读。我家宝宝看了几遍，成色很新，换了大绘本才出，价格比书店便宜不少。您需要英文或者点读的告诉我~', '绘本,中文,英文,点读', '绘本语言与点读说明', 87
  UNION ALL SELECT 'baby_toys', '玩具有3C认证吗？合格吗', '亲，这款玩具有3C认证的，合格~3C认证是国家强制性产品认证，正规玩具都必须有。包装上有3C标志和认证编号可以查。没有3C认证的玩具不要买，可能材料不安全。这款是正规品牌，3C认证齐全，材料安全达标。宝宝玩具安全第一，一定要买有认证的。我家宝宝玩的，正品行货，成色很新，换了大玩具才出，价格很实惠~', '玩具,3C,认证,合格', '玩具3C认证与合格说明', 93
  UNION ALL SELECT 'baby_toys', '这个安抚玩具能机洗吗？', '亲，这款安抚玩具可以手洗，不建议机洗~安抚玩具一般是毛绒的，机洗容易变形掉毛。手洗用温水加婴儿洗衣液轻柔搓洗，然后挤干水分阴干，不要暴晒不要烘干。定期清洗很重要，宝宝天天抱着睡容易滋生细菌。这款我家宝宝用的，成色很新洗过几次，长大了不抱了才出。价格很实惠，您看中了就拍下，洗的时候注意轻柔手洗~', '安抚玩具,机洗,手洗,清洁', '安抚玩具洗涤与清洁', 88
  UNION ALL SELECT 'baby_toys', '拼图木质的有味道吗？甲醛吗', '亲，这款木质拼图没有味道，甲醛达标~正规木质玩具用的是环保漆和环保胶，甲醛释放量达标，不会有刺鼻味道。收到后通风散一下更安心。如果木质玩具有刺鼻味可能是劣质漆胶，不要给宝宝玩。这款是正规品牌有3C认证，我收到时检查过没有异味。我家宝宝玩了2个月，成色很新，换了大拼图才出。宝宝玩具安全第一，正品行货~', '拼图,木质,味道,甲醛', '拼图木质味道与甲醛说明', 91
  UNION ALL SELECT 'baby_toys', '早教机充电还是装电池？续航多久', '亲，这款早教机是充电的，内置锂电池，充满电大概能放5-6小时~充电比换电池方便省钱，USB充电手机充电器就能充。续航5-6小时够用好几天。有低电量提示，快没电会闪烁提醒。充电的时候不能玩，充满大约2小时。我家宝宝听了大半年，电池续航还很好，成色很新，换了大屏早教机才出，价格很实惠~', '早教机,充电,电池,续航', '早教机充电与续航说明', 88
  UNION ALL SELECT 'baby_toys', '玩具原价多少？性价比怎么样', '亲，这款玩具原价一百多，现在出价格很划算~宝宝玩具玩腻了就换，二手的性价比高。这款成色9成新，功能正常没有损坏，价格比新的便宜一半多。宝宝玩具更新快，买二手的换着玩不心疼。我家宝宝玩了2个月不感兴趣了才出，品质没问题。您看中了就拍下，有问题随时找我。我店里还有其他玩具，可以一起看~', '玩具,原价,性价比,二手', '玩具性价比与价格说明', 86
  UNION ALL SELECT 'baby_toys', '这个声光玩具灯光刺眼吗？伤眼吗', '亲，这款声光玩具灯光是柔和的，不刺眼不伤眼~宝宝玩具灯光设计要柔和，太亮的会伤宝宝视力。这款灯光是漫反射柔光，亮度低色彩柔和，不会直射眼睛。而且灯光是间歇闪烁不是持续亮，更安全。我家宝宝玩了没问题。选声光玩具注意灯光不能太亮不能直射。这款有3C认证，灯光安全达标。成色很新，宝宝玩腻了才出~', '声光玩具,灯光,刺眼,伤眼', '声光玩具灯光安全性', 91
  UNION ALL SELECT 'baby_toys', '积木带收纳桶吗？好收拾吗', '亲，这款积木带收纳桶的，好收拾~收纳桶是帆布的，轻便好收纳，宝宝玩完引导宝宝自己收进去，培养收纳习惯。50块积木装一桶刚好。有收纳桶的玩具比散装的好，不会丢也不会乱。我家宝宝玩完都会自己收，好习惯要从小培养。成色很新，换了大积木才出，价格很实惠。您看中了就拍下，带收纳桶很方便~', '积木,收纳桶,收拾,收纳', '积木收纳桶与整理说明', 87
  UNION ALL SELECT 'baby_toys', '绘本有破损吗？缺页吗', '亲，这套绘本我检查过了，没有破损不缺页~宝宝绘本容易被撕，这套我家宝宝看的保护得不错，没有撕破没有缺页，只有轻微翻阅痕迹。成色9成新。我出之前每本都翻过确认完整。绘本缺页撕破了就不好看了，买二手一定要确认。这套正版印刷精美，价格比书店便宜不少。您看中了就拍下，收到检查下，有问题随时找我~', '绘本,破损,缺页,完整', '绘本破损与完整性说明', 89
  UNION ALL SELECT 'baby_toys', '玩具适合男孩女孩？中性吗', '亲，这款玩具是中性的，男女宝宝都能玩~大部分积木、拼图、绘本、早教机都是中性的，不分男女。只有少数玩具分男女，比如洋娃娃偏女孩、车模偏男孩。这款积木男女宝宝都适合，颜色丰富不挑性别。选玩具主要看月龄和兴趣，不用纠结性别。我家宝宝玩的，成色很新，换了大玩具才出，价格很实惠。您看中了就拍下~', '玩具,男孩,女孩,中性', '玩具性别适用与中性说明', 86
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 4. baby_pregnant（孕妇用品）- 30 条
-- ============================================================================
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.55', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'baby_pregnant' AS code, '这个孕妇装什么码？孕几个月能穿' AS question, '亲，这款孕妇装是M码，孕4个月开始能穿~孕妇装一般孕4-5个月肚子显怀了开始穿，到生产都能穿。M码适合孕前100-115斤的。孕妇装要选大一码的，因为肚子会越来越大。这款是托腹设计的，弹性腰围能适应不同孕周。纯棉面料透气舒服。我家生完了才出的，成色很新只穿了一季。您孕几月了？我帮您推荐合适的码~' AS answer, '孕妇装,尺码,月份,托腹' AS tags, '孕妇装尺码与适用孕周' AS source_summary, 89 AS score
  UNION ALL SELECT 'baby_pregnant', '防辐射服真的有用吗？效果怎么样', '亲，防辐射服有一定屏蔽作用，但不是万能的~防辐射服用的是金属纤维面料，能屏蔽日常电器辐射（手机、电脑、wifi），但对医院X光等强辐射没用。日常接触的电器辐射对胎儿影响其实不大，防辐射服更多是心理安慰。如果工作环境辐射多可以穿，日常没必要。这款银纤维的效果比金属纤维好，但贵。我家怀孕时穿过，生完才出，成色很新~', '防辐射服,效果,辐射,屏蔽', '防辐射服效果与说明', 88
  UNION ALL SELECT 'baby_pregnant', '胎心仪安全吗？自己在家能听吗', '亲，胎心仪是安全的，可以自己在家听~家用胎心仪是超声波多普勒的，功率很低对胎儿没有伤害，可以放心使用。一般孕16周以后能听到胎心。听的时候涂耦合剂，在肚脐下方慢慢找，听到咚咚咚的声音就是胎心，正常120-160次/分。不要频繁听，一周1-2次就好，听太久反而焦虑。这款用了几次，生完才出，成色很新，价格很实惠~', '胎心仪,安全,在家,胎心', '胎心仪安全与使用说明', 91
  UNION ALL SELECT 'baby_pregnant', '孕妇枕几个月开始用？好用吗', '亲，孕妇枕一般孕20周以后开始用~肚子大了以后侧睡不舒服，孕妇枕可以垫肚子和腿，减轻腰部压力改善睡眠。U型的能全身包裹，C型的垫一侧。建议左侧卧睡对胎儿好，孕妇枕帮助保持侧卧。这款U型枕我家怀孕时用的，改善睡眠效果很好，生完才出，成色很新。枕套可拆洗。您孕几周了？开始不舒服就可以用了~', '孕妇枕,几个月,U型,侧睡', '孕妇枕适用孕周与效果', 90
  UNION ALL SELECT 'baby_pregnant', '这个月子服纯棉吗？透气吗', '亲，这款月子服是100%纯棉的，透气性好~月子期间出汗多，衣服一定要纯棉透气的，不然闷着不舒服还容易着凉。这款是哺乳款的有哺乳口，方便喂奶不用解开衣服。前开扣设计方便穿脱。宽松不勒。我家月子穿了一个月，成色很新洗过几次，出完月子才出的，价格很实惠。月子里要准备2-3套换洗，这款很合适~', '月子服,纯棉,透气,哺乳', '月子服材质与功能说明', 89
  UNION ALL SELECT 'baby_pregnant', '待产包都有什么？齐全吗', '亲，这个待产包包含：妈妈用品（月子帽、束腹带、产褥垫、一次性内裤、刀纸等）和宝宝用品（奶瓶、纸尿裤、婴儿服、包被、湿巾等）~基本待产需要的东西都有，可能要根据个人情况补充几样。建议孕36周前准备好，避免早产手忙脚乱。这款是全新未拆封的，我家多买了一套才出。价格比单买便宜很多，省心省力，您看中了就拍下~', '待产包,清单,齐全,准备', '待产包清单与准备说明', 90
  UNION ALL SELECT 'baby_pregnant', '防辐射服是银纤维的吗？能洗吗', '亲，这款防辐射服是银纤维的，可以洗但要注意~银纤维比金属纤维屏蔽效果好，但银容易氧化，洗的时候要注意：用中性洗衣液轻柔手洗，不要机洗不要拧干，阴干不要暴晒。洗的次数越少越好，平时不穿用密封袋装好防氧化。银纤维氧化会发黑但不影响效果。这款我家怀孕时穿的，洗过2次，成色很新，生完才出，价格很实惠~', '防辐射服,银纤维,洗涤,氧化', '防辐射服银纤维与洗涤', 88
  UNION ALL SELECT 'baby_pregnant', '孕妇装哺乳口方便喂奶吗？两用吗', '亲，这款孕妇装是哺乳两用的，孕期和哺乳期都能穿~胸部有隐形哺乳口，喂奶时打开就行不用掀衣服，外出喂奶也方便不尴尬。孕期当普通孕妇装穿，生完哺乳期还能继续穿，一衣两穿很实用。弹性面料孕期能适应肚子变大。我家孕期和哺乳期都穿了，成色8成新，断奶了才出。价格很实惠，性价比高，您看中了就拍下~', '孕妇装,哺乳口,两用,喂奶', '孕妇装哺乳两用功能', 89
  UNION ALL SELECT 'baby_pregnant', '胎心仪几成新？用了几次', '亲，这款胎心仪9成新，用了不到10次~我家怀孕时每周听1-2次，用了几个月但每次时间短，所以总次数不多。功能正常声音清晰，耦合剂还剩半瓶一起出。胎心仪不是天天用的，一周几次就够了，所以损耗很小。生完用不上了才出，价格比新的便宜不少。您收到可以先装电池试试，能正常开机听到声音就没问题~', '胎心仪,成色,几次,9成新', '胎心仪成色与使用次数', 87
  UNION ALL SELECT 'baby_pregnant', '孕妇枕 U 型还是 C 型？哪个好', '亲，这款是U型的，U型和C型各有好处~U型枕能同时垫前胸和后背，全身支撑好，但占床大；C型枕只垫一侧，占床小但翻身要换边。如果床大选U型更舒服，床小选C型。U型适合喜欢翻身的孕妈，前后都有支撑。这款U型枕我家用着很舒服，整个孕期睡眠都好了。生完才出，成色很新，枕套可拆洗，价格很实惠~', '孕妇枕,U型,C型,对比', '孕妇枕U型C型对比说明', 89
  UNION ALL SELECT 'baby_pregnant', '月子帽材质怎么样？会闷吗', '亲，这款月子帽是纯棉的，不闷~月子里头部不能受风，要戴帽子保暖。纯棉的透气不闷汗，比化纤的好。松紧合适不勒头。月子里出汗多，帽子要选透气的，不然闷一头汗反而容易着凉。建议备2顶换洗。这款我家月子戴了一个月，成色很新，出完月子才出，价格很实惠。您看中了就拍下，月子里头不能受风要注意~', '月子帽,纯棉,闷,透气', '月子帽材质与透气说明', 86
  UNION ALL SELECT 'baby_pregnant', '待产包为什么出？用不上了吗', '亲，是买多了用不上了才出的~当时怕不够买了两套待产包，结果一套就够了，多的一套全新未拆封。待产包建议孕36周前准备好，里面东西基本都有，可能要根据医院要求补充几样。这款全新未拆封，价格比单买便宜很多。如果您快到预产期了赶紧准备，别到时候手忙脚乱。您看中了就拍下，有问题随时找我~', '待产包,出物,买多,用不上', '待产包出物原因说明', 87
  UNION ALL SELECT 'baby_pregnant', '防辐射服有检测报告吗？真有效吗', '亲，这款防辐射服有检测报告的，屏蔽效果99.9%~有第三方检测机构的报告，屏蔽率达标。不过防辐射服只能屏蔽日常弱辐射，强辐射环境（医院X光室）不能靠它，要专业防护。日常接触的手机电脑wifi辐射对胎儿影响很小，防辐射服更多是心理安慰。这款银纤维的屏蔽效果比金属纤维好。我家怀孕穿过，生完才出，成色很新~', '防辐射服,检测,效果,报告', '防辐射服检测与效果说明', 89
  UNION ALL SELECT 'baby_pregnant', '孕妇托腹带好用吗？会不会勒', '亲，这款托腹带弹性很好不勒，能减轻肚子下坠感~孕晚期肚子大了会有下坠感腰酸，托腹带能托住肚子减轻腰部压力。这款是魔术贴可调节松紧的，贴两指松紧刚好不勒。材质透气网面的不闷。孕7个月以后用比较好，太早肚子小不需要。我家孕晚期用的，缓解腰酸效果不错，生完才出，成色很新，价格很实惠~', '托腹带,孕妇,勒,托腹', '托腹带效果与舒适度', 88
  UNION ALL SELECT 'baby_pregnant', '这个收腹带产后多久能用？有用吗', '亲，收腹带顺产后3天可以开始用，剖腹产要等伤口好些再用（约7-10天）~收腹带能帮助子宫恢复和腹直肌收缩，但要注意不能勒太紧，每天用不要超过8小时，吃饭睡觉时不戴。这款是透气的不会闷。要配合适当运动效果才好，光靠收腹带不能瘦肚子。我家产后用了1-2个月，成色很新，恢复好了才出，价格很实惠~', '收腹带,产后,多久,恢复', '收腹带产后使用与效果', 90
  UNION ALL SELECT 'baby_pregnant', '胎心仪有辐射吗？经常听安全吗', '亲，家用胎心仪是超声波的，功率很低没有辐射，安全~它用的是多普勒超声波，和医院胎心监护原理一样，功率比B超还低，对胎儿没有伤害。可以放心使用。但不要频繁听，一周1-2次就好，每次不超过1分钟。听太频繁反而容易焦虑，胎心偶尔快慢一下是正常的。我家怀孕时每周听1-2次，宝宝很健康。生完才出，成色很新~', '胎心仪,辐射,超声波,安全', '胎心仪辐射与安全说明', 92
  UNION ALL SELECT 'baby_pregnant', '孕妇裤腰围能调节吗？后期还能穿吗', '亲，这款孕妇裤腰围是可调节的，整个孕期都能穿~腰部有弹性V型设计和调节扣，肚子小的时候扣紧，肚子大了松开，从孕初期穿到生产。面料是弹性牛仔布的，舒适有型。托腹部分是柔软针织的不勒肚。我家整个孕期穿这条，成色8成新，生完才出。孕妇裤一定要选可调节腰围的，不然后期穿不下浪费，这款很实用~', '孕妇裤,腰围,调节,弹性', '孕妇裤腰围调节与适用', 88
  UNION ALL SELECT 'baby_pregnant', '月子牙刷软吗？不伤牙龈吗', '亲，这款月子牙刷是超软毛的，不伤牙龈~月子期间牙龈敏感容易出血，要用超软毛牙刷。这款是产妇专用的海绵/超软毛款，轻柔不伤牙龈。月子里不刷牙是错误观念，更要认真刷牙，只是要用软毛的。这款我家月子用的，比普通牙刷舒服很多。成色很新（没用几次），出完月子才出，价格很实惠。月子里口腔卫生很重要~', '月子牙刷,软毛,牙龈,产妇', '月子牙刷软毛与牙龈', 87
  UNION ALL SELECT 'baby_pregnant', '待产包缺什么吗？要不要自己补', '亲，这个待产包基本齐全，可能要补充几样~待产包含妈妈用品和宝宝用品，一般够用。但根据个人习惯可能要补：产妇卫生巾（待产包里的可能不够）、宝宝纸尿裤（要多备）、吸管（躺着喝水用）、保温杯、出院衣服。建议孕36周前准备好，提前检查缺什么补什么。这款全新未拆封，我家多买的才出。您看中了就拍下，省心省力~', '待产包,缺什么,补充,准备', '待产包完整性与补充建议', 88
  UNION ALL SELECT 'baby_pregnant', '防辐射服前穿还是后穿？方便吗', '亲，这款防辐射服是套头前穿的，方便~像穿围裙一样套头穿上，前面有金属纤维屏蔽层覆盖肚子。穿脱方便，里面穿件打底衫外面套防辐射服就行。不要贴身穿，银纤维直接接触皮肤可能过敏。我家怀孕时上班天天穿，穿脱方便不碍事。生完才出，成色很新，洗过2次。价格很实惠，您看中了就拍下，上班对着电脑可以穿~', '防辐射服,穿法,方便,前穿', '防辐射服穿法与便利说明', 86
  UNION ALL SELECT 'baby_pregnant', '孕妇装起球吗？洗了变形吗', '亲，这款孕妇装是纯棉的不起球，洗了不变形~纯棉面料起球率低，比混纺好。洗的时候用冷水轻柔模式，不要暴晒不要高温烘干，这样不变形不缩水。我家穿了整个孕期洗过很多次，没有起球变形褪色。成色8成新，生完才出，价格很实惠。孕妇装要选纯棉的，透气舒服不起球，您看中了就拍下~', '孕妇装,起球,变形,纯棉', '孕妇装起球与洗涤说明', 86
  UNION ALL SELECT 'baby_pregnant', '这个哺乳巾遮得严吗？出门喂奶方便', '亲，这款哺乳巾遮得很严，出门喂奶方便~哺乳巾是围在脖子上的，像个小帐篷罩住宝宝和胸部，前面有硬质支撑条可以看到宝宝不影响视线。外出喂奶不尴尬。面料纯棉透气，宝宝在里面不闷。可折叠放包里很便携。我家哺乳期出门必备的，断奶了才出，成色很新。价格很实惠，哺乳期妈妈外出很实用，您看中了就拍下~', '哺乳巾,遮挡,出门,喂奶', '哺乳巾遮挡与外出便利', 88
  UNION ALL SELECT 'baby_pregnant', '胎心仪能连手机吗？能录音吗', '亲，这款胎心仪不能连手机不能录音，是基础款~基础款只能听胎心声音，不能记录。如果想要连手机录音功能的，我可以推荐智能款，能记录胎心率曲线分享给医生，但贵不少。基础款对日常监测够用了，听到胎心正常就放心。这款我家用着挺好，生完才出，成色很新，价格很实惠。您需要智能款的话告诉我，我帮您推荐~', '胎心仪,手机,录音,智能', '胎心仪功能与智能款说明', 86
  UNION ALL SELECT 'baby_pregnant', '孕妇枕套可拆洗吗？脏了好洗吗', '亲，这款孕妇枕套是可拆洗的，拉链设计拆装方便~枕套是纯棉的，脏了拆下来机洗就行，晾干装回去。建议备2个枕套换洗。内芯不能洗，用久了可以晒一晒杀菌。孕期出汗多枕套要勤洗，一周一次。我家整个孕期用，枕套洗过很多次没有变形褪色。成色很新（内芯），生完才出，价格很实惠。您看中了就拍下~', '孕妇枕,枕套,拆洗,纯棉', '孕妇枕套拆洗与清洁说明', 87
  UNION ALL SELECT 'baby_pregnant', '月子鞋防滑吗？底软吗', '亲，这款月子鞋是防滑软底的，适合月子穿~月子里脚不能受凉，要穿包跟软底鞋。这款底是TPR防滑的，在瓷砖上不滑。鞋底软走路舒服不累。鞋面是纯棉的透气。包跟设计后跟不漏风。月子里走动要注意防滑，摔了很危险。这款我家月子穿了一个月，成色很新，出完月子才出，价格很实惠。您看中了就拍下，月子里脚别受凉~', '月子鞋,防滑,软底,包跟', '月子鞋防滑与软底说明', 87
  UNION ALL SELECT 'baby_pregnant', '这个妊娠油有效果吗？能预防妊娠纹吗', '亲，妊娠油能增加皮肤弹性有一定预防效果，但不能完全避免~妊娠纹主要和遗传、肚子大小、皮肤弹性有关，妊娠油能滋润皮肤增加弹性减轻妊娠纹，但不能完全预防。要从孕早期就开始涂，每天2次按摩吸收。长了纹再涂效果有限。这款是孕妇安全的成分，无维A酸等有害成分。我家怀孕时从4个月开始涂，纹不多，生完才出~', '妊娠油,效果,妊娠纹,预防', '妊娠油效果与预防说明', 89
  UNION ALL SELECT 'baby_pregnant', '防辐射服大小怎么选？孕妇装尺码', '亲，防辐射服选孕前尺码就行，不用买大~防辐射服设计的时候已经考虑了肚子变大的空间，按孕前体重选码就行。比如孕前100-115斤选M码。不要买太大，太大屏蔽层不服帖影响效果。这款是M码的，适合孕前100-115斤。您告诉我孕前体重我帮您选码。我家怀孕时穿的，生完才出，成色很新，价格很实惠~', '防辐射服,尺码,选码,孕前', '防辐射服尺码选择说明', 87
  UNION ALL SELECT 'baby_pregnant', '待产包是品牌吗？质量怎么样', '亲，这个待产包是品牌的，质量不错~里面东西都是正规厂家生产的，不是杂牌。产妇用品和宝宝用品都有质检报告，安全放心。待产包买品牌的主要是省心，不用自己一样样买，一套全搞定。价格比单买便宜很多。这款全新未拆封，我家多买的才出。您快到预产期了赶紧准备，别到时候手忙脚乱。您看中了就拍下，有问题随时找我~', '待产包,品牌,质量,质检', '待产包品牌与质量说明', 88
  UNION ALL SELECT 'baby_pregnant', '孕妇护腰枕办公室能用吗？午休', '亲，这款护腰枕办公室午休能用~它体积不大，放办公室椅子上靠着护腰，午休的时候抱着睡很舒服。孕妇久坐腰容易酸，护腰枕能减轻腰部压力。比U型孕妇枕小巧，便携。这款我家怀孕时办公室放了一个，午休用着很舒服。成色很新，生完才出，价格很实惠。上班族孕妇推荐备一个，护腰很重要，您看中了就拍下~', '护腰枕,孕妇,办公室,午休', '护腰枕办公室适用说明', 87
  UNION ALL SELECT 'baby_pregnant', '这个吸奶器好用吗？电动还是手动', '亲，这款是电动吸奶器，比手动好用~电动的省力效率高，有按摩和吸乳两种模式，先按摩催乳再吸乳，不伤乳腺。双边同时吸比单边快一倍。手动吸奶器便宜但费力，手会酸。建议选电动的，尤其是职场背奶妈妈。这款我家用了几个月，吸力可调节很舒服，成色很新，断奶了才出，价格比新的便宜不少。您看中了就拍下~', '吸奶器,电动,手动,吸乳', '吸奶器电动与手动对比', 90
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 5. baby_clothes（婴幼服装）- 30 条
-- ============================================================================
INSERT INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.55', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'baby_clothes' AS code, '这个婴儿服是 A 类吗？安全吗' AS question, '亲，这款婴儿服是A类婴幼儿标准的，安全~A类是婴幼儿纺织品的最高安全标准，甲醛、pH值、色牢度、异味都严格达标，3岁以下宝宝衣服必须选A类的。B类是成人直接接触皮肤的，C类是非直接接触的。宝宝皮肤娇嫩，衣服一定要A类的。这款有检测报告，标签上标着A类GB31701，您放心。我家宝宝穿的，安全第一~' AS answer, '婴儿服,A类,安全,标准' AS tags, '婴儿服A类安全标准说明' AS source_summary, 94 AS score
  UNION ALL SELECT 'baby_clothes', '衣服会掉色吗？洗了染不染色', '亲，这款婴儿服是活性印染的，不掉色不染色~活性印染比涂料印染环保，色牢度高，洗了不掉色。第一次洗可能有轻微浮色，这是正常的，单独洗一次就好了。深色和浅色分开洗，避免浮色染浅色。宝宝衣服选不掉色的很重要，掉色的衣服染料可能刺激宝宝皮肤。这款我家宝宝穿了洗过多次，没有掉色染色。成色很新，价格很实惠~', '婴儿服,掉色,印染,染色', '婴儿服掉色与印染说明', 91
  UNION ALL SELECT 'baby_clothes', '多大宝宝穿的？身高体重多少合适', '亲，这款是73码的，适合身高70-75cm、体重8-10kg的宝宝，大概6-12个月~宝宝衣服选码主要看身高，身高+10cm就是合适码数（比如身高65cm选73码，宽松一点能多穿段时间）。不要买正好合身的，宝宝长得快，刚好合身的穿一个月就小了。您告诉我宝宝身高体重，我帮您推荐合适的码。这款我家宝宝穿不上了才出，成色很新~', '婴儿服,尺码,身高,体重', '婴儿服尺码与身高体重', 92
  UNION ALL SELECT 'baby_clothes', '含荧光剂吗？宝宝贴身穿安全吗', '亲，这款婴儿服不含荧光剂，贴身穿安全~我用紫光灯验过，没有荧光反应。正规A类婴儿服是不允许含荧光剂的，荧光剂会刺激宝宝皮肤甚至影响健康。便宜的劣质衣服可能有荧光剂让衣服显得白。这款是正规品牌A类的，有检测报告无荧光剂。宝宝贴身衣服一定要选无荧光剂的。我家宝宝穿的，安全第一，正品行货您放心~', '婴儿服,荧光剂,贴身,安全', '婴儿服荧光剂与安全性', 94
  UNION ALL SELECT 'baby_clothes', '这个连体衣纯棉吗？柔软吗', '亲，这款连体衣是100%纯棉的，很柔软~纯棉透气吸汗不刺激皮肤，是宝宝衣服的首选面料。比化纤的好很多，化纤不透气容易过敏。这款是精梳棉的，比普通棉更柔软光滑。摸着就很舒服，宝宝穿着不磨皮肤。我家宝宝穿了洗过几次还是很软，成色很新，穿不上了才出，价格很实惠。宝宝衣服选纯棉的准没错，您看中了就拍下~', '连体衣,纯棉,柔软,精梳棉', '连体衣纯棉与柔软度说明', 91
  UNION ALL SELECT 'baby_clothes', '衣服几成新？穿过几次', '亲，这款衣服9成新，穿过3-4次~宝宝长得快，衣服穿几次就小了，所以成色都很好。这款是别人送的，尺码不合适只穿了几次就穿不上了。没有污渍没有起球，我检查过了。宝宝衣服二手的很划算，因为穿不了几次就小了，九成新的跟新的差不多但便宜很多。您看中了就拍下，有问题随时找我。我店里还有其他码的，可以一起看~', '婴儿服,成色,几次,9成新', '婴儿服成色与穿着次数', 88
  UNION ALL SELECT 'baby_clothes', '婴儿服能机洗吗？会变形吗', '亲，这款婴儿服可以机洗，用轻柔模式不变形~建议用婴儿专用洗衣液，温和不刺激。机洗放洗衣袋里更保护衣服。水温30度以下，不要漂白不要高温烘干，自然晾干就好。纯棉衣服洗了可能有轻微缩水但3%以内不影响穿。我家宝宝衣服都是机洗的，洗过多次没有变形。成色很新，穿不上了才出，价格很实惠。宝宝衣服要和大人衣服分开洗更卫生~', '婴儿服,机洗,变形,洗衣液', '婴儿服机洗与变形说明', 89
  UNION ALL SELECT 'baby_clothes', '这个肚兜材质安全吗？新生儿能用吗', '亲，这款肚兜是A类纯棉的，新生儿能用~肚兜是夏天宝宝穿的，护住肚子不着凉。纯棉透气不闷，A类标准安全。新生儿皮肤娇嫩，衣服一定要A类纯棉的。这款是无骨缝制的，没有硬接缝不磨宝宝皮肤。按扣是树脂的不含金属不会过敏。我家宝宝夏天穿的，成色很新，穿不上了才出，价格很实惠。新生儿夏天备几个肚兜很实用~', '肚兜,纯棉,新生儿,A类', '肚兜材质与新生儿适用', 92
  UNION ALL SELECT 'baby_clothes', '衣服有异味吗？新的是不是要洗', '亲，新衣服建议先洗一遍再穿~虽然这款是A类达标的没有甲醛异味，但生产运输过程中会有浮尘和浆料，洗一遍更干净卫生。用婴儿洗衣液冷水轻柔洗，晾干就能穿。第一次洗可能有轻微浮色，单独洗就好。这款我家宝宝衣服洗过穿了，成色很新。如果您介意全新我可以推荐全新未洗的款。宝宝新衣服一定要先洗再穿，这个习惯要养成~', '婴儿服,异味,新衣服,先洗', '婴儿服异味与首洗说明', 90
  UNION ALL SELECT 'baby_clothes', '连体衣裆部按扣方便换尿布吗', '亲，这款连体衣裆部有按扣，换尿布很方便~裆部按扣一解开就能换尿布，不用脱整件衣服，方便又不会让宝宝着凉。按扣是树脂的，牢固不会自己开也不会伤宝宝皮肤。肩部也是按扣的，领口大方便穿脱不勒头。这款设计很人性化，我家宝宝穿这款换尿布很方便。成色很新，穿不上了才出，价格很实惠。选连体衣一定要选裆部按扣的~', '连体衣,按扣,换尿布,裆部', '连体衣按扣与换尿布便利', 90
  UNION ALL SELECT 'baby_clothes', '这个童装是几码的？几岁穿', '亲，这款童装是110码的，适合身高100-110cm的宝宝，大概3-4岁穿~童装选码主要看身高，身高+5-10cm选码。110码适合105cm左右身高。如果宝宝偏胖选大一码。您告诉我宝宝身高体重我帮您选码。这款是纯棉的，A类安全标准。我家宝宝穿不上了才出，成色很新，价格比新的便宜不少。童装长得快不用买太贵，二手九成新的很划算~', '童装,尺码,几岁,110码', '童装尺码与适用年龄', 89
  UNION ALL SELECT 'baby_clothes', '衣服起球吗？质量怎么样', '亲，这款衣服是精梳棉的不起球~精梳棉比普通棉纤维长不容易起球，而且更柔软光滑。便宜的衣服用普梳棉或者混纺，穿几次就起球。这款质量不错，我家宝宝穿了洗过几次没有起球。成色很新，穿不上了才出。宝宝衣服要选好面料的，贴身穿舒服不过敏。价格很实惠，您看中了就拍下。我店里还有同款其他码的，可以一起看~', '婴儿服,起球,质量,精梳棉', '婴儿服起球与质量说明', 88
  UNION ALL SELECT 'baby_clothes', '婴儿服是和尚服还是连体衣？哪个好', '亲，和尚服和连体衣各有好处~和尚服是前开襟系带的，新生儿穿脱方便不勒肚脐，但容易往上跑露肚子；连体衣裆部按扣不走光不凉肚子，但穿脱稍麻烦。新生儿0-3个月建议和尚服保护脐带，3个月以上可以穿连体衣。这款是连体衣适合3个月以上。我店里也有和尚服，您需要可以看。选哪种看宝宝月龄和季节，您告诉我我帮您推荐~', '婴儿服,和尚服,连体衣,对比', '和尚服与连体衣对比', 90
  UNION ALL SELECT 'baby_clothes', '这个面料透气吗？夏天会闷热吗', '亲，这款是纯棉纱布面料的，透气性很好夏天不闷~纱布棉是多层纯棉纱布叠的，透气吸汗比普通纯棉还好，夏天穿最合适。而且越洗越软。这款是6层纱布的，轻薄透气。我家宝宝夏天穿的，不出疹子不闷热。成色很新，穿不上了才出，价格很实惠。夏天宝宝衣服选纱布棉的最好，透气凉爽，您看中了就拍下~', '婴儿服,透气,夏天,纱布', '婴儿服透气与夏季适用', 90
  UNION ALL SELECT 'baby_clothes', '衣服原价多少？性价比怎么样', '亲，这款原价80多，现在出价格很划算~宝宝衣服穿几次就小了，买全新的贵穿不了多久就浪费。二手九成新的跟新的差不多，价格便宜一半多。这款成色很新，纯棉A类的，品质没问题。宝宝长得快衣服换得勤，买二手的换着穿不心疼。我店里还有很多宝宝衣服，可以一起看搭配着买更划算。您看中了就拍下，有问题随时找我~', '婴儿服,原价,性价比,二手', '婴儿服性价比与价格说明', 87
  UNION ALL SELECT 'baby_clothes', '童装为什么出？穿不下了吗', '亲，是宝宝穿不下了才出的~宝宝长得快，这件穿了2个月就小了。衣服本身成色很好，9成新，没有污渍起球。别人送的尺码买大了，穿了没多久就合适了然后很快又小了。二手宝宝衣服性价比高，因为穿不了几次。我店里还有其他码的，您宝宝穿多大码告诉我，我帮您推荐。您看中了就拍下，有问题随时找我~', '童装,出物,穿不下,长得快', '童装出物原因说明', 86
  UNION ALL SELECT 'baby_clothes', '这个包屁衣适合夏天吗？薄吗', '亲，这款包屁衣是薄款纯棉的，适合夏天穿~包屁衣是连体短袖+短裤的设计，夏天穿凉快不闷。裆部按扣方便换尿布。纯棉薄款透气吸汗。包屁衣是夏天宝宝必备，在家穿一件就够了，方便凉快。我家宝宝夏天穿了好几件换洗，这款穿不上了才出，成色很新。夏天建议备5-6件包屁衣换洗。价格很实惠，您看中了就拍下~', '包屁衣,夏天,薄款,纯棉', '包屁衣夏季与薄款说明', 89
  UNION ALL SELECT 'baby_clothes', '衣服领口大吗？穿脱方便吗', '亲，这款衣服领口是按扣肩开设计的，穿脱方便~肩部按扣打开领口变大，套头穿不勒头不卡耳朵。穿好扣上肩扣就行。比套头领口小的衣服好穿脱，宝宝不哭闹。新生儿头大肩软，套头衣服很难穿，肩开按扣的最好。这款我家宝宝穿的，穿脱很方便不费劲。成色很新，穿不上了才出，价格很实惠。选婴儿服一定要选肩开按扣的，穿脱省事~', '婴儿服,领口,穿脱,肩开', '婴儿服领口与穿脱便利', 90
  UNION ALL SELECT 'baby_clothes', '婴儿袜防滑吗？会掉吗', '亲，这款婴儿袜底部有防滑点胶，不掉不滑~袜口是弹力罗纹的不勒脚不往下掉。底部防滑点胶在地板上走不滑，学步宝宝很需要。纯棉材质透气不闷脚。宝宝袜子要选防滑的不掉的，不然老是滑掉。这款我家宝宝穿了几次，成色很新，穿不上了才出，价格很实惠。学步期宝宝一定要穿防滑袜，摔了危险~', '婴儿袜,防滑,掉,学步', '婴儿袜防滑与不掉说明', 88
  UNION ALL SELECT 'baby_clothes', '这个睡袋厚度多少？什么季节用', '亲，这款睡袋是2.5tog的，适合春秋季或者空调房18-22度~睡袋厚度用tog值表示：0.5tog夏天空调房，1.0tog夏天/初秋，2.5tog春秋/空调房，3.5tog冬天。选睡袋要看室温选厚度。这款2.5tog春秋用最合适。睡袋好处是宝宝踢不掉不着凉，比盖被子省心。我家宝宝用了大半年，成色很新，换了大码才出，价格很实惠。您家室温多少？我帮您推荐合适厚度~', '睡袋,厚度,tog,季节', '睡袋厚度与季节选择', 91
  UNION ALL SELECT 'baby_clothes', '衣服是男宝还是女宝款？中性吗', '亲，这款衣服是中性款的，男女宝都能穿~大部分婴儿服都是中性的，特别是纯色和浅色的。只有少数有明确性别元素（公主裙/汽车图案）的才分男女。这款是浅黄色动物图案的，中性百搭。选婴儿服主要看面料和尺码，不用太纠结性别。我家宝宝穿的，成色很新，穿不上了才出，价格很实惠。您看中了就拍下，男女宝都合适~', '婴儿服,男宝,女宝,中性', '婴儿服性别与中性说明', 86
  UNION ALL SELECT 'baby_clothes', '连体衣会缩水吗？买大一号吗', '亲，纯棉衣服洗了有轻微缩水（3%以内），买大一号刚好~婴儿服一般按身高+10cm选码，大一点的缩水后刚好合身，还能多穿段时间。不要买正好合身的，洗了缩水就小了穿不了几次。这款是73码的，适合身高65-70cm的宝宝，洗了缩水后穿正好。我家宝宝穿不上了才出，成色很新，价格很实惠。您宝宝多高？我帮您选合适的码~', '连体衣,缩水,大一号,选码', '连体衣缩水与选码说明', 89
  UNION ALL SELECT 'baby_clothes', '这个口水巾柔软吗？吸水吗', '亲，这款口水巾是纯棉纱布的，柔软吸水~纱布棉比普通纯棉吸水更好，宝宝流口水能快速吸收不淹脖子。6层纱布柔软不磨皮肤。按扣设计方便穿脱，不像系带的容易松。长牙期宝宝口水多，要多备几个口水巾换洗。这款我家宝宝用的，成色很新，长大了不流口水才出。建议备5-6个换洗。价格很实惠，您看中了就拍下~', '口水巾,柔软,吸水,纱布', '口水巾柔软与吸水说明', 88
  UNION ALL SELECT 'baby_clothes', '衣服按扣牢固吗？会开吗', '亲，这款衣服按扣很牢固，正常穿不会自己开~按扣是树脂按扣，比塑料按扣牢固，扣上咔哒一声就很紧。我家宝宝穿的没有自己开过。按扣比拉链安全，拉链会夹到宝宝肉。比系带方便，系带容易松。选婴儿服按扣的最好。这款我家宝宝穿了洗过多次，按扣依然牢固没有松。成色很新，穿不上了才出，价格很实惠~', '婴儿服,按扣,牢固,树脂', '婴儿服按扣牢固度说明', 87
  UNION ALL SELECT 'baby_clothes', '童装有 3C 标吗？合格吗', '亲，童装看的是GB31701安全标准不是3C~3C是电器玩具的认证，衣服看的是安全类别（A/B/C类）。婴幼儿衣服（36个月以下）必须达到A类GB31701标准。这款标签上明确标着A类GB31701婴幼儿标准，甲醛pH值色牢度都达标，有检测报告。宝宝衣服安全标准比3C更重要，A类是最高标准。我家宝宝穿的，正品行货，安全第一，您放心拍下~', '童装,3C,A类,GB31701', '童装安全标准与A类说明', 92
  UNION ALL SELECT 'baby_clothes', '这个蝴蝶衣新生儿能穿吗？多大码', '亲，这款蝴蝶衣是59码的，新生儿能穿~蝴蝶衣是类似和尚服的前开襟系带款，但下摆像蝴蝶翅膀展开方便换尿布。59码适合新生儿身高50-55cm，一般0-1个月穿。59码不用囤太多，宝宝满月就穿不上了，备3-4件够换洗。这款我家宝宝满月穿不上了才出，成色很新只穿了一个月。价格很实惠。您宝宝多大了？我帮您选合适的码和款式~', '蝴蝶衣,新生儿,59码,尺码', '蝴蝶衣新生儿与尺码说明', 90
  UNION ALL SELECT 'baby_clothes', '衣服一套几件？打包出吗', '亲，这套衣服是3件打包出的，一套买更划算~3件包含2件短袖+1件长袖，可以搭配着穿。单件也可以，但一套买我给优惠。宝宝衣服要多备几件换洗，一天可能换2-3件（吐奶弄脏），建议备10件左右。这套我家宝宝穿不上了才出，成色很新，价格比单买便宜很多。您看中了就拍下，有问题随时找我。我店里还有其他套装可以看~', '婴儿服,一套,几件,打包', '婴儿服套装与打包说明', 87
  UNION ALL SELECT 'baby_clothes', '这个肚围松紧合适吗？会勒吗', '亲，这款肚围松紧很合适不勒~肚围是护肚子的，松紧要刚刚好不能太紧不能太松。这款用的是软弹力松紧，弹性好不勒肚。宝宝肚脐不能着凉，肚围能护住肚子不着凉不拉肚子。夏天空调房或者睡觉时穿很实用。材质是纯棉透气的。我家宝宝用的，成色很新，长大了不用了才出，价格很实惠。您看中了就拍下，护肚子很重要~', '肚围,松紧,勒,护肚', '肚围松紧与护肚说明', 87
  UNION ALL SELECT 'baby_clothes', '婴儿服标签在外还是内？会扎宝宝吗', '亲，这款婴儿服是无感标签设计，标签在外面不会扎宝宝~传统标签缝在领口内侧，会扎宝宝脖子不舒服。无感标签是把信息印在衣服外面，或者标签缝在外侧，宝宝皮肤接触不到。这款是标签缝外侧的，宝宝穿着舒服不扎。A类婴儿服很多都采用无感标签设计。我家宝宝穿的没有因为标签不舒服哭闹过。成色很新，穿不上了才出，价格很实惠~', '婴儿服,标签,扎,无感', '婴儿服标签与无感设计', 89
  UNION ALL SELECT 'baby_clothes', '衣服买回来要洗吗？有甲醛吗', '亲，新衣服一定要先洗再穿~虽然A类衣服甲醛达标，但生产过程中有浆料和浮尘，洗一遍更干净卫生。用婴儿洗衣液冷水轻柔洗，不要漂白不要柔顺剂（柔顺剂可能刺激宝宝皮肤）。第一次洗可能有轻微浮色是正常的，单独洗就好。晾干就能穿。这款A类达标的，甲醛pH值都安全。我家宝宝衣服都是先洗再穿的，这个习惯要养成~', '婴儿服,甲醛,先洗,新衣服', '婴儿服甲醛与首洗说明', 92
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;
